# Surah An-Nahl (chapter 16) — part 3: ayat 21-30 (IDs 1922-1931)
SURAH = 16

ENTRIES = {
1922: (
"وہ مردے ہیں زندہ نہیں — اور یہ نہیں جانتے کہ وہ کب اٹھائے جائیں گے",
"""۱۔ بتوں کی بے جان فطرت؛ وہ خود بے خبر؛ ان کو عبادت کے قابل کیسے قرار دے سکیں۔
۲۔ ’’أَمْوَاتٌ غَيْرُ أَحْيَاءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ‘‘ — وہ مردے ہیں زندہ نہیں — اور یہ نہیں جانتے کہ وہ کب اٹھائے جائیں گے — یعنی وہ مردے ہیں زندہ نہیں — اور یہ نہیں جانتے کہ وہ کب اٹھائے جائیں گے۔
۳۔ عملی سبق: جو خود بے جان ہے وہ دوسروں کو کچھ نہیں دے سکتا؛ صرف اللہ کی عبادت کرو۔"""
),
1923: (
"تمہارا معبود ایک معبود ہے — پس جو آخرت پر ایمان نہیں لاتے ان کے دل انکاری ہیں اور وہ تکبر کرتے ہیں",
"""۱۔ اللہ ایک ہی ہے؛ آخرت کے منکرین بھی دل میں انکاری اور تکبری ہیں۔
۲۔ ’’إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ فَالَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَۃِ قُلُوبُهُم مُّنكِرَۃٌ وَهُم مُّسْتَكْبِرُونَ‘‘ — تمہارا معبود ایک معبود ہے — پس جو آخرت پر ایمان نہیں لاتے ان کے دل انکاری ہیں اور وہ تکبر کرتے ہیں — یعنی تمہارا معبود ایک معبود ہے — پس جو آخرت پر ایمان نہیں لاتے ان کے دل انکاری ہیں اور وہ تکبر کرتے ہیں۔
۳۔ عملی سبق: توحید کی قبولیت دل میں ہونی چاہیے؛ قبول کرنے والا تکبر نہیں کرتا۔"""
),
1924: (
"بلاشبہ اللہ جانتا ہے جو وہ چھپاکر کہتے ہیں اور جو وہ ظاہر کرتے ہیں — بے شک وہ متکبر لوگوں کو پسند نہیں کرتا",
"""۱۔ اللہ ظاہر و باطن سب جانتا ہے؛ تکبری لوگوں سے محبت نہیں؛ ان سے نفرت ہے۔
۲۔ ’’لَا جَرَمَ أَنَّ اللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُ لَا يُحِبُّ الْمُسْتَكْبِرِينَ‘‘ — بلاشبہ اللہ جانتا ہے جو وہ چھپاکر کہتے ہیں اور جو وہ ظاہر کرتے ہیں — بے شک وہ متکبر لوگوں کو پسند نہیں کرتا — یعنی بلاشبہ اللہ جانتا ہے جو وہ چھپا کر کہتے ہیں اور جو وہ ظاہر کرتے ہیں — بے شک وہ متکبر لوگوں کو پسند نہیں کرتا۔
۳۔ عملی سبق: تکبر اللہ کو پسند نہیں؛ تواضع اختیار کرو — یہی ایمان ہے۔"""
),
1925: (
"اور جب ان سے پوچھا جاتا ہے کہ تمہارے رب نے کیا نازل کیا ہے — وہ کہتے ہیں پرانی کہانیاں",
"""۱۔ کفار قرآن کو پرانی کہانی قرار دیتے ہیں؛ یہ ان کی دلیل نہیں بلکہ تعصب ہے۔
۲۔ ’’وَإِذَا قِيلَ لَهُم مَّاذَا أَنزَلَ رَبُّكُمْ قَالُوا أَسَاطِيرُ الْأَوَّلِينَ‘‘ — اور جب ان سے پوچھا جاتا ہے کہ تمہارے رب نے کیا نازل کیا ہے — وہ کہتے ہیں پرانی کہانیاں — یعنی جب ان سے پوچھا جاتا ہے کہ تمہارے رب نے کیا نازل کیا ہے — وہ کہتے ہیں پرانی کہانیاں۔
۳۔ عملی سبق: قرآن کی عظمت کو سمجھ کر ہانی دیکھیں؛ پرانی کہانی نہیں بلکہ اللہ کا کلام ہے۔"""
),
1926: (
"تاکہ وہ قیامت کے دن اپنے بوجھ پورے اٹھائیں — اور ان لوگوں کے بوجھ سے بھی جنہوں نے بغیر علم کے انہیں گمراہ کیا — خبردار — کیا ہی برا وہ بوجھ ہے جو وہ اٹھاتے ہیں",
"""۱۔ گمراہی کی دعوت دینے والے قیامت میں دوہرا وبال اٹھائیں گے؛ یہ ان کی انتہائی بدنصیبی ہے۔
۲۔ ’’لِيَحْمِلُوا أَوْزَارَهُمْ كَامِلَۃً يَوْمَ الْقِيَامَۃِ وَمِنْ أَوْزَارِ الَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ أَلَا سَاءَ مَا يَزِرُونَ‘‘ — تاکہ وہ قیامت کے دن اپنے بوجھ پورے اٹھائیں — اور ان لوگوں کے بوجھ سے بھی جنہوں نے بغیر علم کے انہیں گمراہ کیا — خبردار — کیا ہی برا وہ بوجھ ہے جو وہ اٹھاتے ہیں — یعنی تاکہ وہ قیامت کے دن اپنے بوجھ پورے اٹھا سکیں — اور ان لوگوں کے بوجھ سے بھی جنہوں نے بغیر علم کے انہیں گمراہ کیا — کیا ہی برا وہ بوجھ ہے جو وہ اٹھاتے ہیں۔
۳۔ عملی سبق: کسی کو گمراہ کرنا کتنا بڑا گناہ ہے — اپنے ہر قول پر غور کریں۔"""
),
1927: (
"انہوں نے اپنے سے پہلے بھی مکر کیا — پس اللہ ان کی بنیادیں اُٹھا کر ان پر اپنا عذاب ڈرایا — پس ان کی چھت ان کے اوپر سے گر پڑی اور عذاب ان پر انجان طریقے سے آ گیا",
"""۱۔ پرانی اقوام نے مکر کیا؛ اللہ نے ان کی عمارت کی بنیاد ہلا دی؛ پوری تباہی اچانک آئی۔
۲۔ ’’قَدْ مَكَرَ الَّذِينَ مِن قَبْلِهِمْ فَأَتَى اللَّهُ بُنْيَانَهُم مِّنَ الْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ السَّقْفُ مِن فَوْقِهِمْ وَأَتَاهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ‘‘ — انہوں نے اپنے سے پہلے بھی مکر کیا — پس اللہ ان کی بنیادیں اُٹھا کر ان پر اپنا عذاب ڈرایا — پس ان کی چھت ان کے اوپر سے گر پڑی اور عذاب ان پر انجان طریقے سے آ گیا — یعنی انہوں نے اپنے سے پہلے بھی مکر کیا — پس اللہ ان کی بنیادیں اُٹھا کر ان پر اپنا عذاب ڈرایا — پس ان کی چھت ان کے اوپر سے گر پڑی اور عذاب ان پر بغیر خبر کے آ گیا۔
۳۔ عملی سبق: مکر کا انجام وبال ہے؛ اللہ کی پکڑ غیر شعوری طریقے سے آ سکتی ہے — ہوشیار رہو۔"""
),
1928: (
"پھر قیامت کے دن وہ انہیں رسوا کرے گا اور فرمائے گا — میرے وہ شریک کہاں ہیں جن کے بارے میں تم جھگڑتے تھے — جنہیں علم دیا گیا فرمائیں گے — آج رسوائی اور عذاب کافروں کے لیے ہے",
"""۱۔ قیامت میں بت اور شریک عاجز؛ اہل علم کی بات واضح؛ رسوائی صرف کافروں کے لیے ہے۔
۲۔ ’’ثُمَّ يَوْمَ الْقِيَامَۃِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تُشَاقُّونَ فِيهِمْ قَالَ الَّذِينَ أُوتُوا الْعِلْمَ إِنَّ الْخِزْيَ الْيَوْمَ وَالسُّوءَ عَلَى الْكَافِرِينَ‘‘ — پھر قیامت کے دن وہ انہیں رسوا کرے گا اور فرمائے گا — میرے وہ شریک کہاں ہیں جن کے بارے میں تم جھگڑتے تھے — جنہیں علم دیا گیا فرمائیں گے — آج رسوائی اور عذاب کافروں کے لیے ہے — یعنی پھر قیامت کے دن وہ انہیں رسوا کرے گا اور فرمائے گا — میرے وہ شریک کہاں ہیں جن کے بارے میں تم جھگڑتے تھے — جنہیں علم دیا گیا فرمائیں گے — آج رسوائی اور عذاب کافروں کے لیے ہے۔
۳۔ عملی سبق: اللہ کے شریک ناممکن ہیں؛ علم والوں کی بات ہی یقین ہے؛ اپنی عقائد درست رکھیں۔"""
),
1929: (
"وہ جنہیں فرشتے موت دیتے ہیں جبکہ وہ اپنی جانوں پر ظلم کرتے تھے — پس وہ جھک جائیں گے — ہم نے کوئی برائی نہیں کی — بلکہ بے شک اللہ جانتا ہے جو تم کرتے تھے",
"""۱۔ ظلم موت کے وقت فرشتوں کی اطاعت؛ اپنی خطا تسلیم کرنا بے سود ہے؛ اللہ سب جانتا ہے۔
۲۔ ’’الَّذِينَ تَتَوَفَّاهُمُ الْمَلَائِكَۃُ ظَالِمِي أَنفُسِهِمْ فَأَلْقَوُا السَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوءٍ بَلَىٰ إِنَّ اللَّهَ عَلِيمٌ بِمَا كُنتُمْ تَعْمَلُونَ‘‘ — وہ جنہیں فرشتے موت دیتے ہیں جبکہ وہ اپنی جانوں پر ظلم کرتے تھے — پس وہ جھک جائیں گے — ہم نے کوئی برائی نہیں کی — بلکہ بے شک اللہ جانتا ہے جو تم کرتے تھے — یعنی وہ جنہیں فرشتے موت دیتے ہیں جبکہ وہ اپنی جانوں پر ظلم کرتے تھے — پس وہ جھک جائیں گے اور کہیں گے ہم نے کوئی برائی نہیں کی — بلکہ بے شک اللہ جانتا ہے جو تم کرتے تھے۔
۳۔ عملی سبق: موت کے وقت جھوٹ بڑے کام نہ آئیں گے؛ آج سیدھی راہ چلو۔"""
),
1930: (
"پس جہنم کے دروازوں میں داخل ہو جاؤ — اس میں ہمیشہ رہنے والے ہو — پس تکبر کرنے والوں کا کیا برا ٹھکانہ ہے",
"""۱۔ تکبریوں کا حتمی ٹھکانا جہنم؛ اب کچھ نہیں بچا؛ یہ ان کا انجام ہے۔
۲۔ ’’فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ‘‘ — پس جہنم کے دروازوں میں داخل ہو جاؤ — اس میں ہمیشہ رہنے والے ہو — پس تکبر کرنے والوں کا کیا برا ٹھکانہ ہے — یعنی جہنم کے دروازوں میں داخل ہو جاؤ — تم اس میں ہمیشہ رہو گے — تکبر کرنے والوں کا کیا برا ٹھکانہ ہے۔
۳۔ عملی سبق: تکبر جہنم کا دروازہ ہے؛ نرمی اور عاجزی اختیار کرو۔"""
),
1931: (
"اور ان سے جنہوں نے تقویٰ کیا کہا گیا کہ تمہارے رب نے کیا نازل کیا — انہوں نے کہا خیر — اس دنیا میں بھلائی کرنے والوں کے لیے بھلائی ہے — اور آخرت کا گھر ہی بہتر ہے — اور کیا ہی خوب گھر ہے متقیوں کا",
"""۱۔ اہلِ تقویٰ کے دل مثبت ہیں؛ انہیں قرآن میں خیر معلوم ہوا؛ آخرت ان کا گھر۔
۲۔ ’’وَقِيلَ لِلَّذِينَ اتَّقَوْا مَاذَا أَنزَلَ رَبُّكُمْ قَالُوا خَيْرًا لِّلَّذِينَ أَحْسَنُوا فِي هَٰذِهِ الدُّنْيَا حَسَنَۃٌ وَلَدَارُ الْآخِرَۃِ خَيْرٌ وَلَنِعْمَ دَارُ الْمُتَّقِينَ‘‘ — اور ان سے جنہوں نے تقویٰ کیا کہا گیا کہ تمہارے رب نے کیا نازل کیا — انہوں نے کہا خیر — اس دنیا میں بھلائی کرنے والوں کے لیے بھلائی ہے — اور آخرت کا گھر ہی بہتر ہے — اور کیا ہی خوب گھر ہے متقیوں کا — یعنی ان سے جو تقویٰ رکھتے ہیں کہا گیا کہ تمہارے رب نے کیا نازل کیا — انہوں نے کہا خیر — اس دنیا میں بھلائی کرنے والوں کے لیے بھلائی ہے — اور آخرت کا گھر ہی بہتر ہے — اور کیا خوب گھر ہے متقیوں کا۔
۳۔ عملی سبق: قرآن میں خیر ہی خیر ہے؛ دنیا میں بھلائی کرو — خاص کر کہ آخرت اصل گھر ہے۔"""
),
}
